"use strict";

const { EventEmitter } = require("events");

class JstoolbarCsHandler extends EventEmitter {
  constructor(options = {}) {
    super();
    this.options = { timeout: 5000, retries: 3, ...options };
    this._cache = new Map();
    this._initialized = false;
  }

  async init() {
    if (this._initialized) return;
    this._initialized = true;
    this.emit("ready");
  }

  async process(input) {
    if (!this._initialized) await this.init();
    if (!input) throw new TypeError("Input is required");

    const key = JSON.stringify(input);
    if (this._cache.has(key)) {
      return this._cache.get(key);
    }

    const result = await this._doProcess(input);
    this._cache.set(key, result);
    return result;
  }

  async _doProcess(input) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error("Processing timed out"));
      }, this.options.timeout);

      try {
        const output = this._transform(input);
        clearTimeout(timer);
        resolve(output);
      } catch (err) {
        clearTimeout(timer);
        reject(err);
      }
    });
  }

  _transform(input) {
    if (typeof input === "string") return input.trim();
    if (Array.isArray(input)) return input.filter(Boolean);
    return { ...input };
  }

  destroy() {
    this._cache.clear();
    this._initialized = false;
    this.removeAllListeners();
  }
}

