import { EventEmitter } from "events";

interface DotNewRelationshipsComponentHandlerOptions {
  timeout?: number;
  retries?: number;
  logLevel?: "debug" | "info" | "warn" | "error";
}

interface ProcessResult<T = unknown> {
  data: T;
  meta: { duration: number; cached: boolean };
}

export class DotNewRelationshipsComponentHandler extends EventEmitter {
  private readonly options: Required<DotNewRelationshipsComponentHandlerOptions>;
  private cache = new Map<string, unknown>();
  private initialized = false;

  constructor(options: DotNewRelationshipsComponentHandlerOptions = {}) {
    super();
    this.options = {
      timeout: options.timeout ?? 5000,
      retries: options.retries ?? 3,
      logLevel: options.logLevel ?? "info",
    };
  }

  async init(): Promise<void> {
    if (this.initialized) return;
    this.initialized = true;
    this.emit("ready");
  }

  async process<T>(input: unknown): Promise<ProcessResult<T>> {
    if (!this.initialized) await this.init();
    const start = Date.now();
    const key = JSON.stringify(input);

    if (this.cache.has(key)) {
      return {
        data: this.cache.get(key) as T,
        meta: { duration: Date.now() - start, cached: true },
      };
    }

    const result = await this.doProcess<T>(input);
    this.cache.set(key, result);
    return {
      data: result,
      meta: { duration: Date.now() - start, cached: false },
    };
  }

  private async doProcess<T>(input: unknown): Promise<T> {
    return input as T;
  }

  destroy(): void {
    this.cache.clear();
    this.initialized = false;
    this.removeAllListeners();
  }
}

