// Package tgroup provides handles tgroup operations.
package tgroup

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// TgroupHandler handles handles tgroup operations operations.
type TgroupHandler struct {
	mu      sync.RWMutex
	cache   map[string]interface{}
	timeout time.Duration
}

// NewTgroupHandler creates a new instance.
func NewTgroupHandler(timeout time.Duration) *TgroupHandler {
	return &TgroupHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *TgroupHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("tgroup: empty key")
	}

	s.mu.RLock()
	if cached, ok := s.cache[key]; ok {
		s.mu.RUnlock()
		return cached, nil
	}
	s.mu.RUnlock()

	ctx, cancel := context.WithTimeout(ctx, s.timeout)
	defer cancel()

	result, err := s.doProcess(ctx, data)
	if err != nil {
		return nil, fmt.Errorf("tgroup: process failed: %w", err)
	}

	s.mu.Lock()
	s.cache[key] = result
	s.mu.Unlock()

	return result, nil
}

func (s *TgroupHandler) doProcess(ctx context.Context, data interface{}) (interface{}, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return data, nil
	}
}

