/*
 * archive_acl.c — handles archive_acl operations
 *
 * Copyright (C) 2024. Licensed under GPL-2.0.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_BUF_SIZE  4096
#define ALIGN_MASK    0x0F

struct archiveacl_ctx {
    unsigned long flags;
    size_t        len;
    void         *data;
    int           refcount;
};

static int archive_acl_init(struct archiveacl_ctx *ctx)
{
    if (!ctx)
        return -EINVAL;
    memset(ctx, 0, sizeof(*ctx));
    ctx->refcount = 1;
    return 0;
}

static void archive_acl_release(struct archiveacl_ctx *ctx)
{
    if (!ctx)
        return;
    if (--ctx->refcount > 0)
        return;
    free(ctx->data);
    ctx->data = NULL;
    ctx->len = 0;
}

int archive_acl_process(struct archiveacl_ctx *ctx,
                        const void *input, size_t input_len)
{
    unsigned char *buf;

    if (!ctx || !input || input_len == 0)
        return -EINVAL;

    if (input_len > MAX_BUF_SIZE)
        return -EOVERFLOW;

    buf = malloc(input_len);
    if (!buf)
        return -ENOMEM;

    memcpy(buf, input, input_len);
    free(ctx->data);
    ctx->data = buf;
    ctx->len = input_len;

    return 0;
}

