# subnet_service_initialization — handles subnet_service_initialization operations
module SubnetServiceInitialization
  class SubnetServiceInitializationHandler
    attr_reader :config, :logger

    def initialize(config = {})
      @config = config
      @logger = config.fetch(:logger, Logger.new($stdout))
      @cache = {}
      @mutex = Mutex.new
    end

    def process(input)
      raise ArgumentError, "input required" if input.nil?

      key = input.hash.to_s
      return @cache[key] if @cache.key?(key)

      result = @mutex.synchronize { do_process(input) }
      @cache[key] = result
      result
    end

    def clear_cache
      @mutex.synchronize { @cache.clear }
    end

    private

    def do_process(input)
      validate!(input)
      transform(input)
    end

    def validate!(input)
      return if input.respond_to?(:each)

      raise TypeError, "expected enumerable, got #{input.class}"
    end

    def transform(input)
      input.map { |item| sanitize(item) }
    end

    def sanitize(value)
      case value
      when String then value.strip
      when Hash   then value.compact
      else value
      end
    end
  end
end

