// Package requirement provides handles requirement operations.
package requirement

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// RequirementHandler handles handles requirement operations operations.
type RequirementHandler struct {
	mu      sync.RWMutex
	cache   map[string]interface{}
	timeout time.Duration
}

// NewRequirementHandler creates a new instance.
func NewRequirementHandler(timeout time.Duration) *RequirementHandler {
	return &RequirementHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *RequirementHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("requirement: empty key")
	}

	s.mu.RLock()
	if cached, ok := s.cache[key]; ok {
		s.mu.RUnlock()
		return cached, nil
	}
	s.mu.RUnlock()

	ctx, cancel := context.WithTimeout(ctx, s.timeout)
	defer cancel()

	result, err := s.doProcess(ctx, data)
	if err != nil {
		return nil, fmt.Errorf("requirement: process failed: %w", err)
	}

	s.mu.Lock()
	s.cache[key] = result
	s.mu.Unlock()

	return result, nil
}

func (s *RequirementHandler) doProcess(ctx context.Context, data interface{}) (interface{}, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return data, nil
	}
}

