{
    if (!ctx)
        return -EINVAL;
    memset(ctx, 0, sizeof(*ctx));
    ctx->refcount = 1;
    return 0;
}

static void packetcameltemplate_release(struct packetcameltemplate_ctx *ctx)
{
    if (!ctx)
