// Package ssllabsscanv provides handles ssllabs-scan-v4 operations.
package ssllabsscanv

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// SsllabsScanVHandler handles handles ssllabs-scan-v4 operations operations.
type SsllabsScanVHandler struct {
	mu      sync.RWMutex
	cache   map[string]interface{}
	timeout time.Duration
}

// NewSsllabsScanVHandler creates a new instance.
func NewSsllabsScanVHandler(timeout time.Duration) *SsllabsScanVHandler {
	return &SsllabsScanVHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *SsllabsScanVHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("ssllabsscanv: empty key")
	}

	s.mu.RLock()
	if cached, ok := s.cache[key]; ok {
		s.mu.RUnlock()
		return cached, nil
	}
	s.mu.RUnlock()

	ctx, cancel := context.WithTimeout(ctx, s.timeout)
	defer cancel()

	result, err := s.doProcess(ctx, data)
	if err != nil {
		return nil, fmt.Errorf("ssllabsscanv: process failed: %w", err)
	}

	s.mu.Lock()
	s.cache[key] = result
	s.mu.Unlock()

	return result, nil
}

func (s *SsllabsScanVHandler) doProcess(ctx context.Context, data interface{}) (interface{}, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return data, nil
	}
}

