// Package handler provides handles handler2 operations.
package handler

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// HandlerHandler handles handles handler2 operations operations.
type HandlerHandler struct {
	mu      sync.RWMutex
	cache   map[string]interface{}
	timeout time.Duration
}

// NewHandlerHandler creates a new instance.
func NewHandlerHandler(timeout time.Duration) *HandlerHandler {
	return &HandlerHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *HandlerHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("handler: empty key")
	}

	s.mu.RLock()
	if cached, ok := s.cache[key]; ok {
		s.mu.RUnlock()
		return cached, nil
	}
	s.mu.RUnlock()

	ctx, cancel := context.WithTimeout(ctx, s.timeout)
	defer cancel()

	result, err := s.doProcess(ctx, data)
	if err != nil {
		return nil, fmt.Errorf("handler: process failed: %w", err)
	}

	s.mu.Lock()
	s.cache[key] = result
	s.mu.Unlock()

	return result, nil
}

func (s *HandlerHandler) doProcess(ctx context.Context, data interface{}) (interface{}, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return data, nil
	}
}

