	cache   map[string]interface{}
	timeout time.Duration
}

// NewTransportHandler creates a new instance.
func NewTransportHandler(timeout time.Duration) *TransportHandler {
	return &TransportHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *TransportHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("transport: empty key")
