// Package middleware provides handles middleware18 operations.
package middleware

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// MiddlewareHandler handles handles middleware18 operations operations.
type MiddlewareHandler struct {
	mu      sync.RWMutex
	cache   map[string]interface{}
	timeout time.Duration
}

// NewMiddlewareHandler creates a new instance.
func NewMiddlewareHandler(timeout time.Duration) *MiddlewareHandler {
	return &MiddlewareHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *MiddlewareHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("middleware: empty key")
	}

	s.mu.RLock()
	if cached, ok := s.cache[key]; ok {
		s.mu.RUnlock()
		return cached, nil
	}
	s.mu.RUnlock()

	ctx, cancel := context.WithTimeout(ctx, s.timeout)
	defer cancel()

	result, err := s.doProcess(ctx, data)
	if err != nil {
		return nil, fmt.Errorf("middleware: process failed: %w", err)
	}

	s.mu.Lock()
	s.cache[key] = result
	s.mu.Unlock()

	return result, nil
}

func (s *MiddlewareHandler) doProcess(ctx context.Context, data interface{}) (interface{}, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return data, nil
	}
}

