// Package stack provides handles stack operations.
package stack

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// StackHandler handles handles stack operations operations.
type StackHandler struct {
	mu      sync.RWMutex
	cache   map[string]interface{}
	timeout time.Duration
}

// NewStackHandler creates a new instance.
func NewStackHandler(timeout time.Duration) *StackHandler {
	return &StackHandler{
		cache:   make(map[string]interface{}),
		timeout: timeout,
	}
}

// Process handles a single request.
func (s *StackHandler) Process(ctx context.Context, key string, data interface{}) (interface{}, error) {
	if key == "" {
		return nil, fmt.Errorf("stack: empty key")
	}

	s.mu.RLock()
	if cached, ok := s.cache[key]; ok {
		s.mu.RUnlock()
		return cached, nil
	}
	s.mu.RUnlock()

	ctx, cancel := context.WithTimeout(ctx, s.timeout)
	defer cancel()

	result, err := s.doProcess(ctx, data)
	if err != nil {
		return nil, fmt.Errorf("stack: process failed: %w", err)
	}

	s.mu.Lock()
	s.cache[key] = result
	s.mu.Unlock()

	return result, nil
}

func (s *StackHandler) doProcess(ctx context.Context, data interface{}) (interface{}, error) {
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
		return data, nil
	}
}

