package core.Serializer1;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

/**
 * SerializerHandler — handles Serializer1 operations.
 */
public class SerializerHandler {

    private static final Logger LOG = Logger.getLogger(SerializerHandler.class.getName());
    private final Map<String, Object> cache = new ConcurrentHashMap<>();
    private volatile boolean initialized = false;

    public SerializerHandler() {
        LOG.info("Creating " + getClass().getSimpleName());
    }

    public Object process(Map<String, Object> request) {
        if (request == null || request.isEmpty()) {
            throw new IllegalArgumentException("Request must not be null or empty");
        }
        if (!initialized) {
            synchronized (this) {
                if (!initialized) {
                    initialize();
                    initialized = true;
                }
            }
        }
        String key = (String) request.get("key");
        if (key != null && cache.containsKey(key)) {
            return cache.get(key);
        }
        Object result = doProcess(request);
        if (key != null) {
            cache.put(key, result);
        }
        return result;
    }

    protected void initialize() {
        LOG.info("Initializing " + getClass().getSimpleName());
    }

    protected Object doProcess(Map<String, Object> request) {
        return Collections.unmodifiableMap(request);
    }

    public void shutdown() {
        cache.clear();
        initialized = false;
    }
}

